p=np.pad(s,1)
n=sum(p[1+dy:h+1+dy,1+dx:w+1+dx] for dy in (-1,0,1) for dx in (-1,0,1) if (dx,dy)!=(0,0))
end=(s&(n==1)); branch=(s&(n>=3))
# 8-cc branchpoint cluster
seen=np.zeros_like(s); clusters=[]
for y,x in np.argwhere(branch):
 if seen[y,x]: continue
 stack=[(y,x)];seen[y,x]=1; comp=[]
 while stack:
  yy,xx=stack.pop();comp.append((yy,xx))
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if dx==dy==0:continue
    ny,nx=yy+dy,xx+dx
    if 0<=ny<h and 0<=nx<w and branch[ny,nx] and not seen[ny,nx]: seen[ny,nx]=1;stack.append((ny,nx))
 clusters.append(comp)
print('endpoints',[(int(x),int(y)) for y,x in np.argwhere(end)],'clusters',len(clusters))
# label cluster; find exits to degree2 or endpoint
lab=np.full(s.shape,-1,int)
for i,c in enumerate(clusters):
 for y,x in c:lab[y,x]=i
# track edges from any nodes (clusters + endpoints) along nonbranch pixels
nodes=[]
for i,c in enumerate(clusters):
 ys=[z[0] for z in c];xs=[z[1] for z in c]; nodes.append(('J',i,round(float(np.mean(xs)),1),round(float(np.mean(ys)),1)))
for k,(y,x) in enumerate(np.argwhere(end)):nodes.append(('E',k,int(x),int(y)))
# Edge trace from node's pixels neighbors outside node to next node via degree2
edges=[]
for kind,idx,cx,cy in nodes:
 starts=[]
 if kind=='J': starts=[(y,x) for y,x in clusters[idx]]
 else: starts=[(cy,cx)]
 for sy,sx in starts:
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if dx==dy==0: continue
    yy,xx=sy+dy,sx+dx
    if not(0<=yy<h and 0<=xx<w) or not s[yy,xx]:continue
    if kind=='J' and lab[yy,xx]==idx:continue
    # trace until endpoint or another cluster; avoid branch node start
    prev=(sy,sx); cur=(yy,xx); path=[prev,cur]
    seenpath={prev,cur}
    while True:
     y0,x0=cur
     target=None
     if lab[y0,x0]>=0: target=('J',int(lab[y0,x0]));break
     if end[y0,x0]: target=('E', next(k for k,(ey,ex) in enumerate(np.argwhere(end)) if ey==y0 and ex==x0));break
     neigh=[]
     for ddy in (-1,0,1):
      for ddx in (-1,0,1):
       if ddy==ddx==0:continue
       q=(y0+ddy,x0+ddx)
       if 0<=q[0]<h and 0<=q[1]<w and s[q] and q!=prev:neigh.append(q)
     if not neigh:break
     nxt=neigh[0];prev,cur=cur,nxt
     if cur in seenpath:break
     path.append(cur);seenpath.add(cur)
    if target:
     a=(kind,idx);b=target
     if a<b:
      length=sum(((path[j][0]-path[j-1][0])**2+(path[j][1]-path[j-1][1])**2)**.5 for j in range(1,len(path)))
      edges.append((a,b,round(length,1),(path[0][1],path[0][0]),(path[-1][1],path[-1][0])))
for i,nod in enumerate(nodes[:len(clusters)]): print('J',i,'center',nod[2:],'size',len(clusters[i]))
