def interp(points, step=2.0):
    p=np.asarray(points,dtype=float)
    # Catmull-Rom samples, padded by duplicating endpoints.
    q=np.vstack([p[0],p,p[-1]])
    out=[]
    for i in range(1,len(q)-2):
        a,b,c,d=q[i-1:i+3]
