                if x:d[y,x]=min(d[y,x],d[y,x-1]+1)
                if y and x:d[y,x]=min(d[y,x],d[y-1,x-1]+rt)
                if y and x+1<w:d[y,x]=min(d[y,x],d[y-1,x+1]+rt)
